  ('maternelle-cycle1-cd-2026'::text, 'LANG-S01-C04-O03'::text, 'LANG-S01-C04'::text, 3::smallint, 'Dire ce qu’on a fait et, peu à peu, ce qu’on va faire.'::text, null::text, 'official'::text, 'programme-2024-langage'::text, 6::smallint),
  ('maternelle-cycle1-cd-2026'::text, 'LANG-S01-C04-O04'::text, 'LANG-S01-C04'::text, 4::smallint, 'Prendre part à l’oralisation d’un court texte mémorisé.'::text, null::text, 'official'::text, 'programme-2024-langage'::text, 6::smallint),
