insert into public.lessons (id, curriculum_id, domain_code, title, summary, stage, difficulty, theme_id, parent_guidance, origin, status)
values
  ('m3-art-01'::text, 'maternelle-cycle1-cd-2026'::text, 'ART'::text, 'Je dessine ma famille'::text, 'L’enfant dessine les personnes de sa maison en regardant un modèle, puis parle de son dessin.'::text, 'discovery'::text, 2::smallint, 'la-rentree'::text, 'Ne dessinez pas à la place de l’enfant et ne corrigez pas son dessin. Parlez plutôt de ce qu’il a tracé : c’est le vocabulaire du dessin qui est travaillé ici.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-art-02'::text, 'maternelle-cycle1-cd-2026'::text, 'ART'::text, 'Une comptine pour compter'::text, 'L’enfant apprend et dit une comptine numérique, en jouant avec sa voix.'::text, 'discovery'::text, 1::smallint, 'la-rentree'::text, 'Apprenez la comptine par petits morceaux, en la répétant plusieurs fois : la mémorisation demande de nombreuses répétitions. Vous pouvez la remplacer par une comptine en français connue dans votre famille.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-lang-01'::text, 'maternelle-cycle1-cd-2026'::text, 'LANG'::text, 'Bonjour ! Je me présente'::text, 'L’enfant salue, dit son nom et son âge, et parle des personnes de sa maison.'::text, 'discovery'::text, 1::smallint, 'la-rentree'::text, 'Installez-vous face à l’enfant, au calme. Parlez lentement, en phrases courtes et complètes. Montrez d’abord vous-même : « Bonjour, je m’appelle… » Laissez à l’enfant le temps de répondre ; reformulez sa phrase correctement au lieu de la corriger.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-lang-02'::text, 'maternelle-cycle1-cd-2026'::text, 'LANG'::text, 'Les mots de l’école'::text, 'L’enfant nomme les objets de l’école, puis les range par catégories.'::text, 'discovery'::text, 1::smallint, 'la-rentree'::text, 'Réunissez si possible les objets réels avant de commencer. Un mot n’est appris que s’il est entendu, redit et réutilisé : revenez sur ces mots pendant la journée.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-lang-03'::text, 'maternelle-cycle1-cd-2026'::text, 'LANG'::text, 'J’écoute une histoire'::text, 'L’enfant écoute une courte histoire, puis parle du personnage et de ce qu’il ressent.'::text, 'discovery'::text, 2::smallint, 'la-rentree'::text, 'Installez le calme avant de raconter. Racontez lentement, avec des silences. Ne posez les questions qu’après la fin de l’histoire.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-lang-04'::text, 'maternelle-cycle1-cd-2026'::text, 'LANG'::text, 'Les syllabes et les rimes'::text, 'L’enfant frappe les syllabes des mots, enlève une syllabe, puis cherche des rimes.'::text, 'discovery'::text, 2::smallint, 'la-rentree'::text, 'Ces jeux se font uniquement à l’oreille : n’écrivez rien. Frappez d’abord vous-même, l’enfant répète. Allez lentement, un mot à la fois.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-lang-05'::text, 'maternelle-cycle1-cd-2026'::text, 'LANG'::text, 'Je raconte ma journée'::text, 'L’enfant raconte ce qu’il a fait et ce qu’il fera, puis décrit ce qu’un autre a fait.'::text, 'practice'::text, 2::smallint, 'la-rentree'::text, 'Cette leçon reprend les échanges du premier jour, avec des phrases plus longues. Écoutez sans interrompre, puis redites la phrase de l’enfant au bon temps : « Ce matin, tu as mangé… »'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-math-01'::text, 'maternelle-cycle1-cd-2026'::text, 'MATH'::text, 'Je compte jusqu’à cinq'::text, 'L’enfant dénombre une petite collection, puis constitue une collection d’un nombre donné.'::text, 'discovery'::text, 1::smallint, 'la-rentree'::text, 'Utilisez de vrais objets : cailloux, capsules ou haricots. L’enfant doit déplacer chaque objet en le comptant : c’est le déplacement qui construit le comptage, pas la récitation.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-math-02'::text, 'maternelle-cycle1-cd-2026'::text, 'MATH'::text, 'Plus que, moins que, autant que'::text, 'L’enfant compare deux collections, d’abord à l’œil, puis en comptant.'::text, 'discovery'::text, 2::smallint, 'la-rentree'::text, 'Faites d’abord comparer sans compter, puis vérifier en comptant. Les mots « plus que », « moins que », « autant que » doivent être dits par l’enfant, pas seulement par vous.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-math-03'::text, 'maternelle-cycle1-cd-2026'::text, 'MATH'::text, 'Les formes autour de moi'::text, 'L’enfant nomme le carré, le rectangle, le triangle et le disque, puis les retrouve dans la maison.'::text, 'discovery'::text, 2::smallint, 'la-rentree'::text, 'Employez les mots exacts : un carré a quatre côtés égaux ; on dit un disque, pas un rond. Faites suivre le contour de la forme avec le doigt.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-math-04'::text, 'maternelle-cycle1-cd-2026'::text, 'MATH'::text, 'Trois et deux font cinq'::text, 'L’enfant compose et décompose les nombres jusqu’à cinq, puis dit ce qu’il a fait.'::text, 'practice'::text, 2::smallint, 'la-rentree'::text, 'Cette leçon reprend le comptage du premier jour et va plus loin : l’enfant doit dire à voix haute ce qu’il fait, par exemple « trois et deux, cela fait cinq ».'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-math-05'::text, 'maternelle-cycle1-cd-2026'::text, 'MATH'::text, 'La bande numérique jusqu’à dix'::text, 'L’enfant récite la comptine numérique et remet les nombres de un à dix dans l’ordre.'::text, 'discovery'::text, 3::smallint, 'la-rentree'::text, 'Écrivez les nombres de 1 à 10 sur des morceaux de papier avant de commencer. La bande construite peut rester affichée toute l’année.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-phys-01'::text, 'maternelle-cycle1-cd-2026'::text, 'PHYS'::text, 'Je cours, je m’arrête'::text, 'L’enfant court de plus en plus longtemps et s’arrête au signal.'::text, 'discovery'::text, 1::smallint, 'la-rentree'::text, 'Dégagez un espace sûr, dehors si possible. Le programme demande une activité physique quotidienne : ces quelques minutes à la maison en sont une version courte, à compléter par du jeu libre.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-phys-02'::text, 'maternelle-cycle1-cd-2026'::text, 'PHYS'::text, 'Je vise le panier'::text, 'L’enfant lance une balle de papier vers une cible, de plus en plus loin.'::text, 'discovery'::text, 1::smallint, 'la-rentree'::text, 'Une balle de papier froissé et une boîte suffisent. Faites lancer bras levé, puis de plus en plus loin, sans forcer.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-phys-03'::text, 'maternelle-cycle1-cd-2026'::text, 'PHYS'::text, 'Je danse avec un tissu'::text, 'L’enfant invente et reproduit des gestes dansés, lentement puis vite.'::text, 'discovery'::text, 2::smallint, 'la-rentree'::text, 'Chantez ou tapez un rythme : la musique n’est pas obligatoire. Dansez vous aussi : l’enfant imite d’abord, invente ensuite.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-phys-04'::text, 'maternelle-cycle1-cd-2026'::text, 'PHYS'::text, 'Le parcours de la maison'::text, 'L’enfant enchaîne plusieurs actions : passer sous, monter, marcher en équilibre, sauter.'::text, 'discovery'::text, 2::smallint, 'la-rentree'::text, 'Construisez le parcours avec l’enfant, avec des coussins et des chaises stables. Vérifiez la sécurité avant chaque passage : c’est aussi un objectif du programme.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-phys-05'::text, 'maternelle-cycle1-cd-2026'::text, 'PHYS'::text, 'Le jeu du chat'::text, 'L’enfant joue à attraper et à s’échapper, en respectant la règle et en changeant de rôle.'::text, 'discovery'::text, 2::smallint, 'la-rentree'::text, 'Jouez avec l’enfant, ou avec ses frères et sœurs. Énoncez la règle avant de commencer et arrêtez le jeu si elle n’est plus respectée : la règle fait partie de l’apprentissage.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-time-01'::text, 'maternelle-cycle1-cd-2026'::text, 'TIME-SPACE'::text, 'Les jours de la semaine'::text, 'L’enfant énonce la date du jour et situe un évènement dans la semaine.'::text, 'discovery'::text, 2::smallint, 'la-rentree'::text, 'Reprenez cette question chaque matin, en quelques secondes : c’est la répétition quotidienne qui installe les repères, pas la longueur de la leçon.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-world-01'::text, 'maternelle-cycle1-cd-2026'::text, 'WORLD'::text, 'Mon corps bouge'::text, 'L’enfant nomme les parties du corps et quelques articulations, puis se dessine en mouvement.'::text, 'discovery'::text, 2::smallint, 'la-rentree'::text, 'Faites toucher et bouger chaque partie nommée : le mot se retient mieux quand le corps l’accompagne. Le coude, le genou et l’épaule sont des articulations : ce sont les endroits où le corps plie.'::text, 'teka-edu-created'::text, 'review'::text),
  ('m3-world-02'::text, 'maternelle-cycle1-cd-2026'::text, 'WORLD'::text, 'Les animaux autour de nous'::text, 'L’enfant observe des animaux familiers et dit de quoi ils ont besoin pour vivre.'::text, 'discovery'::text, 2::smallint, 'la-rentree'::text, 'Parlez d’animaux que l’enfant voit vraiment : la poule, la chèvre, le chien, le lézard. Une observation réelle vaut mieux qu’une image.'::text, 'teka-edu-created'::text, 'review'::text)
on conflict (id) do update set
  curriculum_id = excluded.curriculum_id,
  domain_code = excluded.domain_code,
  title = excluded.title,
  summary = excluded.summary,
  stage = excluded.stage,
  difficulty = excluded.difficulty,
  theme_id = excluded.theme_id,
  parent_guidance = excluded.parent_guidance,
  origin = excluded.origin,
  status = excluded.status
where (lessons.curriculum_id, lessons.domain_code, lessons.title, lessons.summary, lessons.stage, lessons.difficulty, lessons.theme_id, lessons.parent_guidance, lessons.origin, lessons.status)
  is distinct from (excluded.curriculum_id, excluded.domain_code, excluded.title, excluded.summary, excluded.stage, excluded.difficulty, excluded.theme_id, excluded.parent_guidance, excluded.origin, excluded.status);

