  ('m3-lang-04-a3'::text, 'en'::text, 'Listen to the story. There are no questions today.'::text),
  ('m3-lang-05-a1'::text, 'en'::text, 'Tell me what you did this morning, then what you will do tomorrow.'::text),
  ('m3-lang-05-a2'::text, 'en'::text, 'Watch what I do, then tell it back in French.'::text),
  ('m3-lang-05-a3'::text, 'en'::text, 'Listen to the story. There are no questions today.'::text),
  ('m3-math-01-a1'::text, 'en'::text, 'Count the stones one by one, then say how many there are.'::text),
  ('m3-math-01-a2'::text, 'en'::text, 'Give me exactly four stones.'::text),
  ('m3-math-02-a1'::text, 'en'::text, 'Which pile has more? Do not count yet.'::text),
