  ('m3-math-05-a2'::text, 'en'::text, 'Put the numbers from one to ten in order.'::text),
  ('m3-phys-01-a1'::text, 'en'::text, 'Run until I clap, then start again.'::text),
  ('m3-phys-02-a1'::text, 'en'::text, 'Throw the ball into the box, then take a step back.'::text),
